def hierarchical_survival(depth, reset_fn, board_size=2):
    if depth == 0:
        return reset_fn(0)
    total = 0
    for _ in range(reset_fn(depth)):
        total += hierarchical_survival(depth - 1, reset_fn, board_size)
    return total

class OrdinalGameValue:
    def __init__(self, depth):
        self.depth = depth
    def __str__(self):
        if self.depth == 0: return 'n (finite)'
        if self.depth == 1: return 'ω'
        return f'ω^{self.depth}'
    def exceeds_finite(self):
        return self.depth >= 1
